import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.jVlskimI.js";const i="/assets/4.BHu-B63F.gif",q=JSON.parse('{"title":"destroyer - 发射器破坏方块","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/4.md","filePath":"plugins/4.md"}'),l={name:"plugins/4.md"};function h(n,a,s,d,c,u){return t(),r("div",{"data-pagefind-body":!0},a[0]||(a[0]=[o('<h1 id="destroyer-发射器破坏方块" tabindex="-1">destroyer - 发射器破坏方块 <a class="header-anchor" href="#destroyer-发射器破坏方块" aria-label="Permalink to &quot;destroyer - 发射器破坏方块&quot;">​</a></h1><blockquote><p>玩家们可以使用这个插件做到在游戏中做出盾构机！</p></blockquote><h2 id="插件用法" tabindex="-1">插件用法 <a class="header-anchor" href="#插件用法" aria-label="Permalink to &quot;插件用法&quot;">​</a></h2><h3 id="发射器最大可以破坏面前的-15-格内的除基岩版以外任意方块" tabindex="-1">发射器最大可以破坏面前的 15 格内的除基岩版以外任意方块 <a class="header-anchor" href="#发射器最大可以破坏面前的-15-格内的除基岩版以外任意方块" aria-label="Permalink to &quot;发射器最大可以破坏面前的 15 格内的除基岩版以外任意方块&quot;">​</a></h3><h3 id="发射器的破坏范围受红石信号等级影响-例如-当红石信号为-7-时-发射器则可以破坏面前的-7-格方块" tabindex="-1">发射器的破坏范围受红石信号等级影响，例如：当红石信号为 7 时，发射器则可以破坏面前的 7 格方块 <a class="header-anchor" href="#发射器的破坏范围受红石信号等级影响-例如-当红石信号为-7-时-发射器则可以破坏面前的-7-格方块" aria-label="Permalink to &quot;发射器的破坏范围受红石信号等级影响，例如：当红石信号为 7 时，发射器则可以破坏面前的 7 格方块&quot;">​</a></h3><h3 id="发射器里只能使用下届合金镐-且不吃任何附魔效果" tabindex="-1">发射器里只能使用下届合金镐，且不吃任何附魔效果 <a class="header-anchor" href="#发射器里只能使用下届合金镐-且不吃任何附魔效果" aria-label="Permalink to &quot;发射器里只能使用下届合金镐，且不吃任何附魔效果&quot;">​</a></h3><h3 id="当发射器内有稿子的时候-则发射器为「破坏状态」-诺在此状态拿下稿子-替换其他物品-发射器则无法投掷物品-需要挖掘再次放置才可结束「破坏状态」" tabindex="-1">当发射器内有稿子的时候，则发射器为「破坏状态」，诺在此状态拿下稿子，替换其他物品，发射器则无法投掷物品，需要挖掘再次放置才可结束「破坏状态」 <a class="header-anchor" href="#当发射器内有稿子的时候-则发射器为「破坏状态」-诺在此状态拿下稿子-替换其他物品-发射器则无法投掷物品-需要挖掘再次放置才可结束「破坏状态」" aria-label="Permalink to &quot;当发射器内有稿子的时候，则发射器为「破坏状态」，诺在此状态拿下稿子，替换其他物品，发射器则无法投掷物品，需要挖掘再次放置才可结束「破坏状态」&quot;">​</a></h3><h3 id="发射器不论破坏什么都只消耗一点耐久" tabindex="-1">发射器不论破坏什么都只消耗一点耐久 <a class="header-anchor" href="#发射器不论破坏什么都只消耗一点耐久" aria-label="Permalink to &quot;发射器不论破坏什么都只消耗一点耐久&quot;">​</a></h3><h3 id="发射器无法破坏基岩-但可以破坏流动水、流动岩浆、静止水、静止岩浆等特殊方块" tabindex="-1">发射器无法破坏基岩，但可以破坏流动水、流动岩浆、静止水、静止岩浆等特殊方块 <a class="header-anchor" href="#发射器无法破坏基岩-但可以破坏流动水、流动岩浆、静止水、静止岩浆等特殊方块" aria-label="Permalink to &quot;发射器无法破坏基岩，但可以破坏流动水、流动岩浆、静止水、静止岩浆等特殊方块&quot;">​</a></h3><h3 id="发射器破坏的物品机制为玩家破坏-例如荧石-玩家破坏则为正常掉落荧石粉" tabindex="-1">发射器破坏的物品机制为玩家破坏，例如荧石，玩家破坏则为正常掉落荧石粉 <a class="header-anchor" href="#发射器破坏的物品机制为玩家破坏-例如荧石-玩家破坏则为正常掉落荧石粉" aria-label="Permalink to &quot;发射器破坏的物品机制为玩家破坏，例如荧石，玩家破坏则为正常掉落荧石粉&quot;">​</a></h3><h3 id="发射器调用了多方-api-使它做到了能正常破坏且掉落模组方块" tabindex="-1">发射器调用了多方 API，使它做到了能正常破坏且掉落模组方块 <a class="header-anchor" href="#发射器调用了多方-api-使它做到了能正常破坏且掉落模组方块" aria-label="Permalink to &quot;发射器调用了多方 API，使它做到了能正常破坏且掉落模组方块&quot;">​</a></h3><h3 id="发射器兼容了领地-再次保护你的领地不受破坏" tabindex="-1">发射器兼容了领地 再次保护你的领地不受破坏 <a class="header-anchor" href="#发射器兼容了领地-再次保护你的领地不受破坏" aria-label="Permalink to &quot;发射器兼容了领地 再次保护你的领地不受破坏&quot;">​</a></h3><p><img src="'+i+'" alt="alt text"></p>',13)]))}const m=e(l,[["render",h]]);export{q as __pageData,m as default};
